  terms: [["Tokenomics", "The design of a token's supply and incentives"], ["Circulating supply", "Tokens available to trade"], ["FDV", "Fully diluted valuation"], ["Vesting", "Gradual release of locked tokens"], ["Cliff", "Initial period with no unlock"], ["Due diligence", "Investigating before trusting"]],
  practical: { title: "Practical: read a tokenomics page", intro: "Find the tokenomics section of any project's documentation.", steps: ["List the allocation percentages.", "Note vesting and cliffs.", "Compute market cap and FDV.", "List one healthy sign and one red flag."] },
